    function run(uint256 burnAmount) public {
        require(burnAmount > 0);

        address owner = c.owner();
        uint256 beforeBalance = c.balanceOf(owner);
        uint256 beforeTotal = c.totalSupply();

        bool reverted;
        if (beforeBalance >= burnAmount) {
            try c.burn(burnAmount) {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(!reverted);
            assert(c.balanceOf(owner) == beforeBalance - burnAmount);
            assert(c.totalSupply() == beforeTotal - burnAmount);
        } else {
            try c.burn(burnAmount) {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(reverted);
            assert(c.balanceOf(owner) == beforeBalance);
            assert(c.totalSupply() == beforeTotal);
        }
    }
