contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address target, bool freeze, address recipient, uint256 amount) public {
        require(target != address(0));
        require(recipient != address(0));

        // ensure target has sufficient balance to attempt a transfer
        c.mintToken(target, amount);

        // owner freezes target
        c.freezeAccount(target, freeze);

        // record balances before attempted transfers
        uint256 targetBefore = c.balanceOf(target);
        uint256 recipientBefore = c.balanceOf(recipient);

        // attempt transfer from frozen target
        bool fromFrozenReverted;
        try c.transfer(recipient, amount) {
            fromFrozenReverted = false;
        } catch {
            fromFrozenReverted = true;
        }

        // attempt transfer to frozen target
        bool toFrozenReverted;
        try c.transfer(target, amount) {
            toFrozenReverted = false;
        } catch {
            toFrozenReverted = true;
        }

        // general rule: if freeze is true, both transfers must revert
        // and balances must remain unchanged; if freeze is false, no such guarantee is asserted
        assert(
            freeze ? (fromFrozenReverted && toFrozenReverted &&
                      c.balanceOf(target) == targetBefore &&
                      c.balanceOf(recipient) == recipientBefore)
                   : true
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address target, address sender, uint256 amount) public {
        require(target != address(0));
        require(sender != address(0));
        require(target != sender);

        // Give sender enough tokens so the transfer would otherwise succeed: mint to sender
        c.mintToken(sender, amount);

        // Freeze the target account
        c.freezeAccount(target, true);

        // Record balances before the attempted transfer to the frozen target
        uint256 senderBefore = c.balanceOf(sender);
        uint256 targetBefore = c.balanceOf(target);

        // Attempt to transfer from sender to frozen target. This must revert.
        bool reverted;
        try c.transfer(target, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: transferring to a frozen target always reverts,
        // and the balances of sender and target remain unchanged.
        assert(reverted && c.balanceOf(sender) == senderBefore && c.balanceOf(target) == targetBefore);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address to) public payable {
        require(to != address(0));
        require(!c.frozenAccount(to));

        uint256 ownerBalBefore = c.balanceOf(address(this));
        uint256 toBalBefore = c.balanceOf(to);
        uint256 supplyBefore = c.totalSupply();
        require(ownerBalBefore > 0);

        bool reverted;
        try c.transfer(to, ownerBalBefore) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(c.balanceOf(address(this)) == 0);
            assert(c.balanceOf(to) == toBalBefore + ownerBalBefore);
        }
        assert(c.totalSupply() == supplyBefore);
    }
}

